window.SBL_LESSONS['HD-t1-l1-measuring-human'] = {
  id: 'HD-t1-l1-measuring-human',
  topicNumber: 1,
  topicTitle: 'Development opportunities',
  title: 'Measuring human development',
  href: '/geography/paper-2/hl-2/t1-development/l1-measuring-human',
  syllabusFocus: 'The multidimensional process of human development and ways to measure it: UN Sustainable Development Goals (SDG) criteria, and the validity and reliability of development indicators and indices, including the Human Development Index (HDI) and Gender Inequality Index (GII).',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is human development?', request: 'Explain the multidimensional process of human development' },
    { label: 'The Sustainable Development Goals', request: 'Explain the UN Sustainable Development Goals (SDGs) as a way of measuring development' },
    { label: 'The Human Development Index', request: 'Explain what the Human Development Index (HDI) measures and how it is calculated' },
    { label: 'The Gender Inequality Index', request: 'Explain what the Gender Inequality Index (GII) measures' },
    { label: 'Validity and reliability', request: 'Explain what validity and reliability mean in the context of development indicators' },
    { label: 'Comparing composite indicators', request: 'Compare the effectiveness of the SDGs, HDI and GII as ways of measuring development' },
    { label: 'Help me evaluate an indicator', request: 'Help me practise writing an evaluation of a development indicator using terms like validity, composite and multi-dimensional' }
  ],
  checklist: [
    'I can identify a variety of ways in which development can be measured and evaluate them.',
    'I can compare the effectiveness of three composite human development indicators \u2014 the SDGs, HDI and GII.',
    'I can use terms such as validity, composite, multi-dimensional and equality when making an evaluation.'
  ],
  readinessQuestions: [
    'Why is human development described as "multidimensional"?',
    'What is the Human Development Index (HDI), and what does it combine?',
    'What is the Gender Inequality Index (GII) designed to measure?',
    'What is the difference between validity and reliability when evaluating a development indicator?',
    'What is one strength and one limitation of using a composite indicator like the HDI?'
  ],
  quiz: [
    { q: 'Human development is described as "multidimensional" because it:', options: ['Can only be measured using a single economic statistic', 'Involves multiple interconnected dimensions of wellbeing, such as health, education and income, rather than one single factor', 'Has no relationship to a country\u2019s income level', 'Only applies to high-income countries'], correct: 1, explain: 'Human development is described as multidimensional because it involves multiple interconnected dimensions of wellbeing \u2014 such as health, education and income \u2014 rather than being captured by a single economic factor alone.', misconception: 'Development is sometimes reduced to just "how rich a country is," when the multidimensional concept recognises that health, education and other factors are equally important.', tag: 'What is human development?' },
    { q: 'The UN Sustainable Development Goals (SDGs) are best described as:', options: ['A single numerical indicator of a country\u2019s wealth', 'A set of 17 interconnected global goals covering a wide range of social, economic and environmental targets', 'A ranking system based only on GDP per capita', 'A measure used exclusively for high-income countries'], correct: 1, explain: 'The SDGs are a set of 17 interconnected global goals, adopted by the United Nations, covering a wide range of social, economic and environmental targets that countries are encouraged to work towards by 2030.', misconception: 'The SDGs are sometimes assumed to be a single composite score like the HDI, when they are actually a broader framework of 17 distinct goals covering many different aspects of development.', tag: 'The Sustainable Development Goals' },
    { q: 'The Human Development Index (HDI) combines indicators relating to:', options: ['Only a country\u2019s GDP per capita', 'Life expectancy, education (expected and mean years of schooling), and gross national income per capita', 'Only literacy rates', 'A country\u2019s population size'], correct: 1, explain: 'The HDI combines three dimensions: life expectancy at birth (health), education (expected and mean years of schooling), and gross national income (GNI) per capita, producing a composite score that reflects development more broadly than income alone.', misconception: 'The HDI is sometimes assumed to be based purely on income, when it specifically combines health and education indicators alongside income to give a more rounded picture of development.', tag: 'The Human Development Index' },
    { q: 'The Gender Inequality Index (GII) measures inequality between men and women across which dimensions?', options: ['Only differences in average height', 'Reproductive health, empowerment (such as political representation and education), and labour market participation', 'Only differences in life expectancy', 'A country\u2019s total population'], correct: 1, explain: 'The GII measures gender-based inequality across three dimensions: reproductive health, empowerment (such as parliamentary representation and secondary education attainment), and labour market participation.', misconception: 'The GII is sometimes confused with simply measuring the number of women in a population, when it actually measures inequality of outcomes and opportunities between men and women across several dimensions.', tag: 'The Gender Inequality Index' },
    { q: 'A GII score closer to 0 indicates:', options: ['Greater inequality between men and women', 'Greater equality between men and women', 'A country with no population data available', 'A country with a very low HDI score'], correct: 1, explain: 'On the GII scale, a score closer to 0 indicates greater equality between men and women across the measured dimensions, while a score closer to 1 indicates greater inequality.', misconception: 'It is worth double-checking the direction of any index rather than assuming; for the GII specifically, a lower score is generally the more favourable outcome, representing less inequality.', tag: 'The Gender Inequality Index' },
    { q: 'Validity, as it relates to a development indicator, refers to:', options: ['Whether an indicator produces the same result every time it is measured', 'Whether an indicator actually measures what it claims to measure', 'The total number of countries included in an indicator', 'The visual design of a graph showing the indicator'], correct: 1, explain: 'Validity refers to whether an indicator genuinely measures what it claims to measure \u2014 for example, whether GNI per capita is a valid measure of overall "development" or only captures the economic dimension.', misconception: 'Validity and reliability are sometimes used interchangeably, but validity specifically concerns whether the indicator measures the right thing, while reliability concerns consistency of measurement.', tag: 'Validity and reliability' },
    { q: 'Reliability, as it relates to a development indicator, refers to:', options: ['Whether an indicator measures the correct concept', 'Whether an indicator produces consistent, repeatable results when measured in the same way over time', 'The number of dimensions included in a composite indicator', 'Whether an indicator is published by the United Nations'], correct: 1, explain: 'Reliability refers to whether an indicator produces consistent, repeatable results when measured using the same method \u2014 for example, whether life expectancy data is collected and calculated consistently across different countries and years.', misconception: 'Reliability is sometimes confused with accuracy or validity; reliability specifically concerns the consistency of the measurement process itself, separate from whether it measures the "right" concept.', tag: 'Validity and reliability' },
    { q: 'A composite indicator, such as the HDI, is one that:', options: ['Is based on a single statistic with no further calculation', 'Combines multiple individual indicators into a single overall score or index', 'Only measures economic factors', 'Cannot be compared between different countries'], correct: 1, explain: 'A composite indicator, such as the HDI, combines multiple individual indicators (like life expectancy, education and income) into a single overall score or index, aiming to provide a more rounded measure than any single statistic alone.', misconception: 'A single overall number is sometimes assumed to be a "simple" indicator, when a composite indicator like the HDI is actually the product of combining several underlying measures together.', tag: 'Comparing composite indicators' },
    { q: 'A key limitation shared by composite indicators like the HDI and GII is that they:', options: ['Are always perfectly accurate with no possible criticism', 'Combine multiple factors into a single score, which can mask important variation between the underlying dimensions or within a country', 'Cannot be calculated for any country', 'Only measure a single dimension of development'], correct: 1, explain: 'A key limitation of composite indicators like the HDI and GII is that combining multiple factors into a single score can mask important variation \u2014 a country might score well overall while performing poorly on one specific underlying dimension, or while hiding significant inequality within the country.', misconception: 'A composite score is sometimes treated as a complete, unambiguous picture, when it is important to also examine the underlying component indicators to understand what is really driving the overall score.', tag: 'Comparing composite indicators' },
    { q: 'When evaluating the effectiveness of the SDGs, HDI and GII together as ways of measuring development, geographers would consider that:', options: ['Only one of these three indicators is ever considered useful', 'Each captures a different aspect of development, so using them together provides a more complete picture, though each also has its own limitations regarding validity and reliability', 'They all measure exactly the same thing and are interchangeable', 'These indicators cannot be applied to real-world case studies'], correct: 1, explain: 'A strong evaluation recognises that the SDGs (a broad goal framework), HDI (a composite of health/education/income) and GII (a composite of gender-based inequality) each capture a different aspect of development, so considering them together gives a more complete picture, while also acknowledging that each has its own specific limitations around validity and reliability.', misconception: 'Evaluation is sometimes reduced to simply naming a limitation of one indicator, when a stronger response compares strengths and weaknesses across multiple indicators and considers how using them together can offset individual limitations.', tag: 'Comparing composite indicators' }
  ]
};

window.SBL_LESSONS['HD-t1-l2-empowering'] = {
  id: 'HD-t1-l2-empowering',
  topicNumber: 1,
  topicTitle: 'Development opportunities',
  title: 'Empowering women, indigenous and minority groups',
  href: '/geography/paper-2/hl-2/t1-development/l2-empowering',
  syllabusFocus: 'Detailed illustrative examples of affirmative action to close the development gap, including affirmative action to promote gender equality for women in Nepal, action supporting LGBTQ+ communities as a minority group, and the impact of outside influences and affirmative action on the Dani people of Irian Jaya.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is affirmative action?', request: 'Define affirmative action and give examples as it pertains to minority groups' },
    { label: 'Women in Nepal', request: 'Explain how affirmative action in Nepal has helped bring about greater gender equality' },
    { label: 'LGBTQ+ affirmative action', request: 'Explain a basic example of affirmative action supporting LGBTQ+ communities as a minority group' },
    { label: 'The Dani people of Irian Jaya', request: 'Explain how the Dani people of Irian Jaya have been impacted by outside influences' },
    { label: 'Affirmative action for the Dani', request: 'Describe the affirmative action taken by Christian missionaries and the Indonesian government regarding the Dani people' },
    { label: 'Why affirmative action is used', request: 'Explain why governments and organisations use affirmative action to close the development gap' },
    { label: 'Evaluating affirmative action', request: 'Help me evaluate the effectiveness of affirmative action as a strategy' }
  ],
  checklist: [
    'I can define and give examples of \u2018affirmative action\u2019 as it pertains to minority groups.',
    'I can describe how affirmative action in Nepal can help bring about greater gender equality.',
    'I can identify how the Dani people of Irian Jaya have been impacted by outside influences and describe the affirmative action taken by Christian missionaries and the Indonesian government.'
  ],
  readinessQuestions: [
    'What is affirmative action, and who might it be aimed at?',
    'What is one example of affirmative action supporting gender equality for women in Nepal?',
    'What is one example of affirmative action supporting LGBTQ+ communities as a minority group?',
    'Who are the Dani people, and how have they been impacted by outside influences?',
    'What affirmative action has been taken in relation to the Dani people, by whom?'
  ],
  quiz: [
    { q: 'Affirmative action, as it pertains to minority groups, refers to:', options: ['Policies that reduce support for disadvantaged groups', 'Deliberate policies or measures aimed at improving opportunities and reducing inequality for groups that have historically faced discrimination or disadvantage', 'A term unrelated to social or gender equality', 'A policy that applies only to majority population groups'], correct: 1, explain: 'Affirmative action refers to deliberate policies or measures aimed at improving opportunities and reducing inequality for groups that have historically faced discrimination or disadvantage, such as women, indigenous peoples, or other minority groups.', misconception: 'Affirmative action is sometimes assumed to be a single specific policy, when it actually describes a broad category of deliberate measures that can take many different forms depending on the group and context.', tag: 'What is affirmative action?' },
    { q: 'Affirmative action to promote gender equality for women in Nepal has included measures such as:', options: ['Reducing women\u2019s access to education and political participation', 'Reserved seats or quotas for women in political representation, and initiatives to improve women\u2019s access to education and economic opportunity', 'Banning women from all forms of employment', 'A complete absence of any government policy on gender equality'], correct: 1, explain: 'Affirmative action in Nepal supporting gender equality has included measures such as reserved seats or quotas for women in political representation, alongside initiatives aimed at improving women\u2019s access to education and economic opportunity.', misconception: 'Gender equality initiatives are sometimes assumed to happen automatically as a country develops, when specific, deliberate affirmative action policies (like reserved political seats) have been a key mechanism driving change in Nepal.', tag: 'Women in Nepal' },
    { q: 'A basic example of affirmative action supporting LGBTQ+ communities as a minority group would be:', options: ['Removing all legal recognition or protections for LGBTQ+ individuals', 'Introducing anti-discrimination laws or policies that specifically protect LGBTQ+ individuals in areas such as employment or legal recognition', 'A policy with no relevance to development or human rights', 'A measure that only applies to majority population groups'], correct: 1, explain: 'A basic example of affirmative action supporting LGBTQ+ communities includes introducing anti-discrimination laws or policies that specifically protect LGBTQ+ individuals, such as employment protections or legal recognition of same-sex relationships, aiming to reduce disadvantage faced by this minority group.', misconception: 'Affirmative action is sometimes thought of only in terms of gender or ethnicity, when it can apply to a range of minority groups, including those defined by sexual orientation or gender identity.', tag: 'LGBTQ+ affirmative action' },
    { q: 'The Dani people are an indigenous group located in:', options: ['Northern Europe', 'Irian Jaya (the Indonesian part of the island of New Guinea)', 'South America', 'The Arabian Peninsula'], correct: 1, explain: 'The Dani are an indigenous people located in the highlands of Irian Jaya, the Indonesian-administered western half of the island of New Guinea.', misconception: 'The specific location of the Dani people is sometimes uncertain to students; they are specifically an indigenous group of the Irian Jaya highlands in Indonesia.', tag: 'The Dani people of Irian Jaya' },
    { q: 'Outside influences that have impacted the Dani people have historically included:', options: ['Complete isolation with no contact from outside groups', 'Contact with Christian missionaries and integration efforts by the Indonesian government, which have brought significant cultural and economic change', 'Only positive economic benefits with no cultural disruption', 'A situation identical to every other indigenous group worldwide'], correct: 1, explain: 'Outside influences on the Dani people have historically included contact with Christian missionaries, who introduced new religious beliefs, alongside integration efforts by the Indonesian government, both of which have brought significant cultural, economic and social change to traditional Dani ways of life.', misconception: 'Outside influence on indigenous groups is sometimes assumed to be a single simple process, when it typically involves multiple actors (such as religious missionaries and government bodies) each bringing distinct forms of change.', tag: 'The Dani people of Irian Jaya' },
    { q: 'Affirmative action taken by Christian missionaries in relation to the Dani people has typically included:', options: ['Efforts to eliminate all forms of formal education', 'Establishing schools, healthcare provision, and religious education, alongside promoting changes to some traditional practices', 'A complete refusal to interact with the Dani community', 'Actions unrelated to health or education'], correct: 1, explain: 'Christian missionaries working with the Dani people have typically taken actions such as establishing schools and providing healthcare, alongside religious education, while also promoting changes to some traditional practices, as part of broader efforts to support development alongside religious conversion.', misconception: 'Missionary influence is sometimes considered only in religious terms, when it has often also included practical affirmative action such as establishing schools and healthcare services.', tag: 'Affirmative action for the Dani' },
    { q: 'Affirmative action taken by the Indonesian government in relation to the Dani people has typically included:', options: ['Complete exclusion of the Dani from national development programmes', 'Integration policies, infrastructure development, and efforts to bring the Dani into the wider Indonesian education and economic system', 'Recognition of the Dani region as a fully independent nation', 'A policy of total non-interference with no government involvement at all'], correct: 1, explain: 'The Indonesian government has pursued integration policies towards the Dani people, including infrastructure development and efforts to bring the Dani into the wider Indonesian education and economic system, as part of national development strategy for the Irian Jaya region.', misconception: 'Government affirmative action towards indigenous groups is sometimes assumed to be purely protective in nature, when in the case of the Dani, government policy has also actively pursued integration into the wider national system, which itself has both benefits and disadvantages worth evaluating.', tag: 'Affirmative action for the Dani' },
    { q: 'A general reason governments and organisations use affirmative action to close the development gap is that:', options: ['Development gaps close automatically without any deliberate intervention', 'Historically disadvantaged groups may face structural barriers that prevent them from accessing opportunities equally, requiring deliberate, targeted policies to help close the gap', 'Affirmative action has never been shown to have any effect', 'Only economic factors are relevant to closing a development gap'], correct: 1, explain: 'Affirmative action is used because historically disadvantaged groups often face structural barriers (such as discrimination, limited access to education, or exclusion from political processes) that prevent equal access to opportunities, meaning deliberate, targeted policies are often needed to help close the resulting development gap.', misconception: 'Development gaps are sometimes assumed to close naturally over time without intervention, when geographers recognise that structural barriers often persist unless deliberately addressed through targeted policy.', tag: 'Why affirmative action is used' },
    { q: 'A challenge sometimes associated with affirmative action policies, worth considering in an evaluation, is that they:', options: ['Always achieve their goals with no possible criticism or debate', 'Can sometimes generate debate or resistance from groups who feel they are disadvantaged by the policy, even while aiming to reduce inequality for another group', 'Have no relevance to real-world case studies like Nepal or the Dani people', 'Only ever apply to a single country in the world'], correct: 1, explain: 'A genuine evaluative point is that affirmative action policies can sometimes generate debate or resistance, including from groups who feel they are disadvantaged by the policy, even while the policy aims to reduce inequality for a different, historically disadvantaged group \u2014 this tension is a recognised part of evaluating such policies.', misconception: 'Affirmative action is sometimes presented as universally accepted and uncontroversial, when a stronger evaluation recognises that such policies can generate genuine debate, which is worth acknowledging even while explaining their intended benefits.', tag: 'Evaluating affirmative action' },
    { q: 'Comparing the Nepal, LGBTQ+, and Dani examples of affirmative action together illustrates that:', options: ['Affirmative action only ever takes a single identical form regardless of context', 'Affirmative action can take many different forms (such as political quotas, anti-discrimination law, or missionary/government integration efforts) depending on the specific group and context involved', 'Only gender-based affirmative action is a valid example of this concept', 'These three examples have no meaningful similarities or differences worth comparing'], correct: 1, explain: 'Comparing these three examples together illustrates that affirmative action can take many different forms depending on the specific group and context \u2014 from political quotas (Nepal), to anti-discrimination law (LGBTQ+ communities), to missionary and government-led integration efforts (the Dani) \u2014 showing the breadth of what this concept can encompass.', misconception: 'It is sometimes assumed affirmative action always looks the same, when comparing multiple real-world examples together shows how varied the specific mechanisms and actors involved can be.', tag: 'What is affirmative action?' }
  ]
};

window.SBL_LESSONS['HD-t1-l3-the-importance'] = {
  id: 'HD-t1-l3-the-importance',
  topicNumber: 1,
  topicTitle: 'Development opportunities',
  title: 'The importance of social entrepreneurship for human development \u2014 micro-finance and \u2018Fairtrade\u2019',
  href: '/geography/paper-2/hl-2/t1-development/l3-the-importance',
  syllabusFocus: 'The importance of social entrepreneurship approaches for human development, including micro-finance schemes and Fairtrade, using illustrative examples such as the Grameen Bank, Kiva and KickStart.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is social entrepreneurship?', request: 'Define social entrepreneurship and explain how it differs from ordinary entrepreneurship' },
    { label: 'What is micro-finance?', request: 'Explain what micro-finance is and how it supports human development' },
    { label: 'The Grameen Bank', request: 'Explain the Grameen Bank as an example of a micro-finance social enterprise' },
    { label: 'Kiva', request: 'Explain how Kiva works as a micro-finance social enterprise' },
    { label: 'KickStart', request: 'Explain how KickStart works as a social enterprise' },
    { label: 'What is Fairtrade?', request: 'Explain what Fairtrade is and how it supports human development' },
    { label: 'Evaluating social entrepreneurship', request: 'Help me evaluate the importance of social entrepreneurship for human development' }
  ],
  checklist: [
    'I can define what social entrepreneurship is and how it differs from ordinary entrepreneurship.',
    'I can explain how micro-finance schemes, such as the Grameen Bank and Kiva, support human development.',
    'I can explain how Fairtrade supports human development.'
  ],
  readinessQuestions: [
    'What is the key difference between an ordinary entrepreneur and a social entrepreneur?',
    'What is micro-finance, and how does it aim to support development?',
    'What is the Grameen Bank, and what is it known for?',
    'How does Kiva work as a micro-finance platform?',
    'What is Fairtrade, and how does it aim to support producers in developing countries?'
  ],
  quiz: [
    { q: 'A social entrepreneur is best defined as someone who:', options: ['Starts a business purely to maximise personal financial profit', 'Recognises a social problem and uses entrepreneurial principles to organise, create and manage a venture that drives social change', 'Only donates money to charity without running any kind of venture', 'Has no connection to solving social problems'], correct: 1, explain: 'A social entrepreneur recognises a social problem and uses entrepreneurial principles \u2014 such as innovation, risk-taking and business strategy \u2014 to organise, create and manage a venture that drives social change, rather than purely pursuing financial profit.', misconception: 'Social entrepreneurship is sometimes confused with simple charitable giving; a social entrepreneur specifically runs a venture using business methods to achieve social goals, which is a distinct approach from donating to an existing charity.', tag: 'What is social entrepreneurship?' },
    { q: 'A key difference between an ordinary entrepreneurial venture and a social entrepreneurial venture is that:', options: ['Ordinary ventures aim primarily for financial gain, while social ventures aim to drive social change using business solutions, with sustainability and social impact as the measure of success', 'They are identical in every respect', 'Social ventures never generate any revenue', 'Ordinary ventures always have a social purpose'], correct: 0, explain: 'Ordinary entrepreneurial ventures primarily aim to serve markets with new products or services for financial gain, while social entrepreneurial ventures aim to drive social change using business solutions, measuring success through sustainability and social impact rather than profit alone.', misconception: 'It is sometimes assumed social ventures cannot generate any revenue, when many social enterprises do generate income \u2014 the key distinction is that profits are reinvested towards the social mission rather than distributed purely for private financial gain.', tag: 'What is social entrepreneurship?' },
    { q: 'Micro-finance is best defined as:', options: ['Very large loans given exclusively to established multinational corporations', 'Small loans, savings, and other financial services provided to individuals or small businesses, often in low-income communities, who typically lack access to traditional banking', 'A term unrelated to development or poverty reduction', 'A government tax policy'], correct: 1, explain: 'Micro-finance refers to small loans, savings accounts, and other financial services provided to individuals or small businesses, often in low-income communities, who typically lack access to traditional banking services, aiming to support entrepreneurship and reduce poverty.', misconception: 'Micro-finance is sometimes confused with traditional large-scale bank lending; the defining feature is specifically small-scale loans aimed at those excluded from conventional banking, often without requiring traditional collateral.', tag: 'What is micro-finance?' },
    { q: 'The Grameen Bank, founded by Muhammad Yunus, is significant as an example of micro-finance because it:', options: ['Only provides loans to already wealthy individuals', 'Pioneered providing small, collateral-free loans to some of the poorest people, particularly to support their own income-generating activities', 'Refuses to lend to anyone in a developing country', 'Has no connection to poverty reduction'], correct: 1, explain: 'The Grameen Bank, founded by Muhammad Yunus, pioneered providing small, collateral-free "micro-loans" to some of the poorest individuals, particularly aimed at helping them start or grow their own income-generating activities as a route out of extreme poverty.', misconception: 'Traditional banking typically requires collateral to secure a loan; the Grameen Bank\u2019s significance lies partly in demonstrating that collateral-free lending to very poor borrowers could still be a viable and effective model.', tag: 'The Grameen Bank' },
    { q: 'Kiva operates as a micro-finance platform by:', options: ['Providing loans exclusively from large financial institutions', 'Allowing regular individuals around the world to provide small loans directly to small business owners in developing countries via the internet', 'Refusing to allow individuals to track the progress of loans they have contributed to', 'Operating only within a single country'], correct: 1, explain: 'Kiva allows regular individuals ("investors") around the world to provide small loans to small business owners in developing countries via the internet, with lenders able to track the progress of the business they have supported, and repaid funds becoming "Kiva Credit" that can be used to fund further loans.', misconception: 'Kiva is sometimes assumed to be a traditional charity that simply gives away money, when its specific model is based on facilitating peer-to-peer loans (which are generally repaid), distinguishing it from a pure donation-based charity.', tag: 'Kiva' },
    { q: 'KickStart is an example of a social enterprise that focuses on:', options: ['Providing luxury goods to wealthy consumers', 'Promoting sustainable growth and employment creation in developing countries by developing technologies that entrepreneurs can use to establish small-scale enterprises', 'Discouraging any form of local entrepreneurship', 'A venture entirely unrelated to economic development'], correct: 1, explain: 'KickStart, founded by Martin Fisher and Nick Moon, focuses on promoting sustainable growth and employment creation in developing countries by developing technologies (such as low-cost irrigation pumps) that local entrepreneurs can use to establish and run their own small-scale enterprises.', misconception: 'KickStart is sometimes assumed to directly hand out finished products for free, when its model is centred on providing accessible technology that enables local entrepreneurs to build sustainable businesses themselves.', tag: 'KickStart' },
    { q: 'Fairtrade is best defined as a certification and movement that aims to:', options: ['Reduce the prices paid to producers in developing countries as much as possible', 'Ensure producers, particularly in developing countries, receive a fairer price and better trading conditions for their goods, such as coffee or cocoa', 'Eliminate all international trade in agricultural goods', 'Apply only to goods produced in high-income countries'], correct: 1, explain: 'Fairtrade is a certification and movement that aims to ensure producers, particularly in developing countries, receive a fairer price and improved trading conditions for goods such as coffee, cocoa or tea, helping support more stable incomes and improved development outcomes for producer communities.', misconception: 'Fairtrade is sometimes assumed to simply be a marketing label with no real economic mechanism behind it, when it specifically involves minimum price guarantees and trading standards designed to directly benefit producers.', tag: 'What is Fairtrade?' },
    { q: 'A company combining corporate social responsibility with a product like Fairtrade coffee (as with the Starbucks example) illustrates that:', options: ['A company emphasising corporate social responsibility (CSR) is automatically the same thing as being a dedicated social enterprise', 'CSR initiatives by a large company are a distinct concept from a dedicated social enterprise, even though both can support similar development goals', 'CSR has no connection to Fairtrade in any way', 'Large companies are never involved in any form of social responsibility'], correct: 1, explain: 'A company emphasising corporate social responsibility (CSR), such as a large coffee chain sourcing Fairtrade coffee, is considered a distinct concept from being a dedicated social enterprise \u2014 a social enterprise has social impact as its core defining purpose, while a company\u2019s CSR initiative is one part of a broader business primarily focused on other goals.', misconception: 'CSR initiatives and social enterprises are sometimes treated as identical, when geographers distinguish between a company doing socially responsible things alongside its main business (CSR) and a venture whose core mission is specifically social change (a social enterprise).', tag: 'Evaluating social entrepreneurship' },
    { q: 'A recognised benefit of micro-finance and Fairtrade approaches for human development is that they:', options: ['Have no measurable impact on poverty or income for participants', 'Can provide direct economic opportunities and improved income stability for individuals and communities who may otherwise lack access to traditional financial systems or fair market prices', 'Only benefit large multinational corporations', 'Are identical in their approach and mechanism'], correct: 1, explain: 'A recognised benefit of both micro-finance and Fairtrade is that they can provide direct economic opportunities and improved income stability for individuals and communities who may otherwise lack access to traditional financial systems (in the case of micro-finance) or fair market prices for their goods (in the case of Fairtrade).', misconception: 'Micro-finance and Fairtrade are sometimes treated as the same mechanism, when they operate quite differently \u2014 one provides access to credit/finance, the other guarantees fairer trading terms for goods \u2014 even though both aim to support similar development outcomes.', tag: 'Evaluating social entrepreneurship' },
    { q: 'When evaluating the overall importance of social entrepreneurship approaches like micro-finance and Fairtrade for human development, geographers would consider:', options: ['That these approaches always succeed with no possible limitations worth discussing', 'Both the genuine benefits (such as improved income and opportunity) and potential limitations (such as limited scale, or debt risk in the case of micro-finance) together', 'That these approaches have no relevance whatsoever to development geography', 'Only the marketing appeal of these approaches, with no attention to actual outcomes'], correct: 1, explain: 'A strong evaluation of social entrepreneurship approaches considers both genuine benefits (such as improved income, opportunity and market access) alongside potential limitations (such as the limited overall scale of many schemes, or the risk of debt for micro-finance borrowers who struggle to repay), rather than presenting these approaches as either wholly positive or wholly ineffective.', misconception: 'Evaluation is sometimes reduced to simply listing positive outcomes, when geographers are expected to weigh up both the genuine strengths and the real limitations of any development approach, including social entrepreneurship.', tag: 'Evaluating social entrepreneurship' }
  ]
};

window.SBL_LESSONS['HD-t1-l4-tncs-and'] = {
  id: 'HD-t1-l4-tncs-and',
  topicNumber: 1,
  topicTitle: 'Development opportunities',
  title: 'TNCs and Corporate Social Responsibility',
  href: '/geography/paper-2/hl-2/t1-development/l4-tncs-and',
  syllabusFocus: 'The importance of social entrepreneurship approaches for human development: TNC corporate social responsibility frameworks and global agreements, and the increasing level of global interdependence and the need for sustainable development.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is CSR?', request: 'Define Corporate Social Responsibility (CSR)' },
    { label: 'IKEA and sustainability', request: 'Explain how IKEA can make progress towards sustainability as an example of a TNC and CSR' },
    { label: 'International Framework Agreements', request: 'Explain what International Framework Agreements (IFAs) are and give examples' },
    { label: 'How IFAs support development', request: 'Explain how International Framework Agreements can contribute to human development' },
    { label: 'Global interdependence', request: 'Explain the increasing level of global interdependence between countries and companies' },
    { label: 'The need for sustainable development', request: 'Explain why global interdependence creates a need for sustainable development' },
    { label: 'Evaluating CSR', request: 'Help me evaluate the effectiveness of CSR as a strategy for human development' }
  ],
  checklist: [
    'I can define Corporate Social Responsibility (CSR).',
    'I can make reference to IKEA in describing how a TNC can make progress towards sustainability.',
    'I can give examples of International Framework Agreements (IFAs) and describe how they can contribute to human development.'
  ],
  readinessQuestions: [
    'What is Corporate Social Responsibility (CSR)?',
    'How does IKEA illustrate a TNC making progress towards sustainability?',
    'What is an International Framework Agreement (IFA)?',
    'How can IFAs contribute to human development?',
    'Why does increasing global interdependence create a need for sustainable development?'
  ],
  quiz: [
    { q: 'Corporate Social Responsibility (CSR) is best defined as:', options: ['A legal requirement with no flexibility for any company', 'A company\u2019s voluntary commitment to operate in ways that consider social, environmental and economic impacts, beyond the minimum legal requirements', 'A tax paid exclusively by transnational corporations', 'A term unrelated to sustainability or human development'], correct: 1, explain: 'Corporate Social Responsibility refers to a company\u2019s voluntary commitment to operate in ways that consider its social, environmental and economic impacts, often going beyond the minimum legal requirements, and can include areas such as sustainable sourcing, labour standards, and community investment.', misconception: 'CSR is sometimes assumed to be a strict legal obligation, when it more accurately describes voluntary commitments that can vary significantly in genuine impact and ambition between different companies.', tag: 'What is CSR?' },
    { q: 'IKEA is used as an example of a TNC making progress towards sustainability partly because it has:', options: ['No sustainability initiatives of any kind', 'Pursued initiatives such as sourcing more sustainable materials, investing in renewable energy, and setting emissions and waste reduction targets across its supply chain', 'Reduced its business operations to a single country', 'Eliminated all forms of manufacturing entirely'], correct: 1, explain: 'IKEA is used as a CSR/sustainability example because it has pursued initiatives such as sourcing more sustainable materials (like FSC-certified wood), investing in renewable energy for its stores and operations, and setting targets to reduce emissions and waste across its global supply chain.', misconception: 'Large TNCs are sometimes assumed to have no genuine sustainability commitments, when companies like IKEA have made specific, trackable commitments across their supply chains, even though the overall effectiveness and pace of such commitments remains a legitimate topic for evaluation.', tag: 'IKEA and sustainability' },
    { q: 'An International Framework Agreement (IFA) is best defined as:', options: ['A trade agreement between two neighbouring countries only', 'A formal agreement, typically between a TNC and a global trade union federation, setting minimum labour and social standards across the company\u2019s international operations', 'A term unrelated to labour rights or corporate responsibility', 'A binding agreement enforced only within a single factory'], correct: 1, explain: 'An International Framework Agreement (IFA) is a formal agreement, typically negotiated between a TNC and a global trade union federation, setting minimum labour and social standards that are intended to apply consistently across the company\u2019s international operations and supply chain.', misconception: 'IFAs are sometimes confused with ordinary national labour laws; their distinctive feature is that they are negotiated specifically to apply consistent standards across a TNC\u2019s multiple international operations, rather than being tied to a single country\u2019s legal system.', tag: 'International Framework Agreements' },
    { q: 'IFAs can contribute to human development because they:', options: ['Have no connection to labour conditions or workers\u2019 rights', 'Can help establish consistent minimum labour and social standards (such as fair wages, safe working conditions, and the right to unionise) across a TNC\u2019s global operations, including in countries with weaker national labour protections', 'Only apply to a company\u2019s operations in its home country', 'Prevent any form of international trade union involvement'], correct: 1, explain: 'IFAs can contribute to human development by helping establish consistent minimum labour and social standards \u2014 such as fair wages, safe working conditions, and the right to unionise \u2014 across a TNC\u2019s global operations, including in countries where national labour protections may otherwise be weaker.', misconception: 'The potential development impact of IFAs is sometimes overlooked, when consistent labour standards across a TNC\u2019s international supply chain can have a meaningful effect on working conditions and rights for large numbers of workers in developing countries.', tag: 'How IFAs support development' },
    { q: 'Global interdependence, as it relates to TNCs and CSR, refers to:', options: ['Countries and companies operating in complete isolation from one another', 'The increasing degree to which countries, companies and supply chains are interconnected and reliant on one another across the world', 'A term unrelated to global trade or TNCs', 'A decreasing trend in international business connections'], correct: 1, explain: 'Global interdependence refers to the increasing degree to which countries, companies and supply chains are interconnected and reliant on one another across the world, meaning decisions and standards set by a TNC in one location can have significant effects on workers, communities and environments elsewhere.', misconception: 'Global interdependence is sometimes discussed only in terms of trade flows, when it also has direct relevance to how TNC behaviour (including CSR commitments) in one location can affect development outcomes in very different parts of the world.', tag: 'Global interdependence' },
    { q: 'The increasing level of global interdependence creates a need for sustainable development partly because:', options: ['Actions taken by a TNC or country in one location can have significant social, economic or environmental consequences elsewhere in an interconnected global system', 'Interdependence has no relevance to environmental or social sustainability', 'Countries operating independently face no shared global challenges', 'Sustainable development is only relevant to a single country at a time'], correct: 0, explain: 'Because countries, companies and supply chains are so interconnected, actions taken in one location \u2014 such as unsustainable resource extraction, poor labour practices, or high emissions \u2014 can have significant social, economic or environmental consequences elsewhere in the interconnected global system, creating a shared need for sustainable, responsible practices.', misconception: 'Sustainability challenges are sometimes framed as purely local or national issues, when the interconnected nature of global trade and TNC operations means that sustainable development genuinely requires coordinated, international approaches.', tag: 'The need for sustainable development' },
    { q: 'A recognised limitation of relying on voluntary CSR commitments (rather than binding international law) is that they:', options: ['Are always fully enforced with no possible gaps', 'May vary significantly in ambition and genuine implementation between different companies, since they are not legally mandated in the same way as national or international law', 'Have no relevance to sustainable development', 'Apply identically and automatically to every TNC without exception'], correct: 1, explain: 'A recognised limitation of voluntary CSR commitments is that, because they are not legally mandated in the same binding way as national or international law, they can vary significantly in ambition and genuine implementation between different companies, making outcomes less consistent than a legally enforced standard would be.', misconception: 'CSR commitments are sometimes assumed to carry the same binding force as law, when their voluntary nature means genuine implementation and ambition can vary considerably between companies, which is an important point to raise in a balanced evaluation.', tag: 'Evaluating CSR' },
    { q: 'Compared to voluntary CSR commitments, International Framework Agreements (IFAs) are generally considered to offer:', options: ['Weaker commitments with no negotiation involved', 'A more formally negotiated commitment, often involving trade unions, which can provide a stronger basis for consistent labour standards across a TNC\u2019s operations', 'Identical strength and enforceability to a purely voluntary CSR statement', 'No meaningful difference from an ordinary company press release'], correct: 1, explain: 'Compared to purely voluntary, unilateral CSR commitments, IFAs are generally considered to offer a more formally negotiated commitment, often involving trade unions as a negotiating partner, which can provide a somewhat stronger and more accountable basis for consistent labour standards across a TNC\u2019s international operations.', misconception: 'IFAs and general CSR statements are sometimes treated as equivalent, when the negotiated, agreement-based nature of an IFA (typically involving a union partner) distinguishes it from a company unilaterally announcing its own voluntary CSR policy.', tag: 'International Framework Agreements' },
    { q: 'When evaluating IKEA\u2019s sustainability initiatives as an example of TNC CSR, a balanced response would consider:', options: ['Only the positive sustainability commitments IKEA has made, with no further analysis', 'Both the genuine progress made (such as specific sourcing and energy targets) and legitimate questions about the pace, scale, and verification of these commitments relative to the company\u2019s overall global impact', 'That IKEA\u2019s sustainability initiatives have no relevance to CSR as a concept', 'That all TNC sustainability claims should be dismissed without any consideration of genuine progress'], correct: 1, explain: 'A balanced evaluation of IKEA\u2019s sustainability initiatives considers both the genuine, specific progress made (such as sourcing and energy targets) and legitimate questions worth raising about the pace, scale, and independent verification of these commitments relative to the company\u2019s overall global environmental and social footprint.', misconception: 'Evaluations of TNC sustainability claims sometimes fall into an all-positive or all-negative extreme, when geographers are expected to weigh up genuine progress alongside legitimate critical questions about scale and verification.', tag: 'IKEA and sustainability' },
    { q: 'The relationship between global interdependence, TNCs, and sustainable development illustrates that:', options: ['These three concepts have no meaningful connection to one another', 'As TNCs and global supply chains become more interconnected, their CSR practices and agreements like IFAs become increasingly significant tools for pursuing sustainable development at a global scale', 'Sustainable development is achievable through national policy alone, with no role for TNCs', 'Global interdependence makes sustainable development entirely unnecessary'], correct: 1, explain: 'This lesson illustrates that as TNCs and global supply chains become more interconnected through growing global interdependence, tools such as CSR practices and formally negotiated agreements like IFAs become increasingly significant mechanisms for pursuing sustainable development at a genuinely global scale, extending beyond what any single national government could achieve alone.', misconception: 'Sustainable development is sometimes considered purely a matter of national government policy, when the interconnected, global nature of TNC operations means that corporate-level mechanisms like CSR and IFAs also play a genuinely significant role.', tag: 'The need for sustainable development' }
  ]
};

window.SBL_LESSONS['HD-t2-l1-culture'] = {
  id: 'HD-t2-l1-culture',
  topicNumber: 2,
  topicTitle: 'Changing identities and cultures',
  title: 'Culture, ethnicity and identity',
  href: '/geography/paper-2/hl-2/t2-changing/l1-culture',
  syllabusFocus: 'The global spectrum of cultural traits, ethnicities and identities, and ways in which the spectrum of diversity is widening or narrowing at different scales, using terminology including culture, expression of culture, cultural trait, ethnicity, cultural differentialism, indigenous, cultural hybridisation, cultural homogenisation/convergence, cultural dilution, westernisation, homogenisation of landscapes, cultural imperialism/imposition, and detraditionalisation.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is culture?', request: 'Define culture, cultural traits, and the expression of culture' },
    { label: 'Ethnicity vs culture', request: 'Explain the difference between ethnicity and culture' },
    { label: 'Cultural differentialism', request: 'Explain what cultural differentialism means' },
    { label: 'Homogenisation vs hybridisation', request: 'Explain the difference between cultural homogenisation and cultural hybridisation' },
    { label: 'Westernisation and cultural imperialism', request: 'Explain westernisation and cultural imperialism' },
    { label: 'The global spectrum of culture', request: 'Explain what is meant by the global spectrum of culture, and how it can widen or narrow' },
    { label: 'Help with local examples', request: 'Give me examples of a global culture at both a global and local scale, such as at an international school' }
  ],
  checklist: [
    'I can use a wide range of terminology related to culture, ethnicity and diversity.',
    'I can identify the aspects of a \u2018global culture\u2019, on a global scale and a local scale.',
    'I can describe ethnic diversity in a place and comment on how this reflects a spectrum of diversity.'
  ],
  readinessQuestions: [
    'What is the difference between culture and ethnicity?',
    'What is a cultural trait, and can you give an example?',
    'What is the difference between cultural homogenisation and cultural hybridisation?',
    'What does westernisation mean?',
    'What does it mean to say the "spectrum of diversity" is widening or narrowing at different scales?'
  ],
  quiz: [
    { q: 'Culture is best defined as:', options: ['A fixed, unchangeable set of beliefs held by every member of a country', 'The shared beliefs, values, customs, behaviours and artefacts that characterise a group of people', 'A term used only to describe language', 'A synonym for a country\u2019s political system'], correct: 1, explain: 'Culture refers to the shared beliefs, values, customs, behaviours and artefacts (such as food, clothing, art and traditions) that characterise a particular group of people.', misconception: 'Culture is sometimes reduced to a single element like language or food, when it is a broad concept encompassing many shared aspects of a group\u2019s way of life.', tag: 'What is culture?' },
    { q: 'A cultural trait is best described as:', options: ['An entire national culture', 'A single, specific element of a culture, such as a particular style of dress, food, or custom', 'A term unrelated to culture', 'Only applicable to religious practices'], correct: 1, explain: 'A cultural trait is a single, specific element of a culture \u2014 such as a particular style of dress, a food dish, a custom, or a form of music \u2014 rather than the entire culture as a whole.', misconception: 'A cultural trait is sometimes confused with an entire culture; it specifically refers to one identifiable component within a broader culture.', tag: 'What is culture?' },
    { q: 'Ethnicity differs from culture mainly because it:', options: ['Is exactly the same concept as culture', 'Often refers to a group sharing a common ancestry, heritage or nationality, which may or may not align exactly with shared cultural practices', 'Has no connection to identity at all', 'Only applies to religious groups'], correct: 1, explain: 'Ethnicity typically refers to a group sharing a common ancestry, heritage or national origin, which is related to but distinct from culture \u2014 members of the same ethnic group may share cultural traits, but ethnicity is more specifically about shared heritage and identity.', misconception: 'Culture and ethnicity are sometimes used interchangeably, but ethnicity is more specifically tied to shared ancestry/heritage, while culture is the broader set of shared practices and values.', tag: 'Ethnicity vs culture' },
    { q: 'Cultural differentialism refers to:', options: ['The idea that all cultures are becoming identical', 'The view or process by which distinct cultural identities and differences are maintained and preserved, resisting a single global culture', 'A term unrelated to culture or globalisation', 'The complete elimination of cultural diversity'], correct: 1, explain: 'Cultural differentialism refers to the view or process by which distinct cultural identities and differences are maintained and preserved, often as a response or resistance to the idea of a single, homogenised global culture.', misconception: 'Cultural differentialism is sometimes confused with homogenisation, which describes the opposite process; differentialism is specifically about the persistence of distinct cultural differences.', tag: 'Cultural differentialism' },
    { q: 'Cultural homogenisation (or convergence) refers to:', options: ['Cultures becoming increasingly similar to one another, often through the spread of a dominant global culture', 'Cultures becoming increasingly distinct and different from one another', 'A term unrelated to globalisation', 'A process that only affects language'], correct: 0, explain: 'Cultural homogenisation, also called cultural convergence, describes the process by which cultures become increasingly similar to one another, often through the widespread influence of a dominant global culture, such as through media, brands or consumer products.', misconception: 'Homogenisation is sometimes confused with hybridisation; homogenisation specifically describes cultures becoming more similar/uniform, whereas hybridisation describes cultures blending to create something new.', tag: 'Homogenisation vs hybridisation' },
    { q: 'Cultural hybridisation refers to:', options: ['One culture completely replacing another with no blending', 'The blending of two or more cultures to create a new, mixed cultural form', 'The complete elimination of all cultural diversity', 'A term unrelated to cultural change'], correct: 1, explain: 'Cultural hybridisation describes the blending of two or more cultures to create a new, mixed cultural form \u2014 for example, fusion cuisine or music genres that combine elements from different cultural traditions.', misconception: 'Hybridisation is sometimes confused with one culture simply dominating or replacing another; hybridisation specifically describes a genuine blending that creates something new from multiple cultural influences.', tag: 'Homogenisation vs hybridisation' },
    { q: 'Westernisation refers to:', options: ['The spread of any random cultural traits regardless of origin', 'The adoption of cultural traits, values, and practices associated with Western (particularly North American and European) societies by other cultures around the world', 'A process unrelated to cultural change', 'A term that only applies to economic systems'], correct: 1, explain: 'Westernisation describes the adoption of cultural traits, values and practices associated with Western societies \u2014 particularly North American and European culture \u2014 by other cultures around the world, often linked to globalisation and media influence.', misconception: 'Westernisation is sometimes used as a general synonym for "modernisation," when it specifically refers to the spread of culturally Western traits and values, not simply economic or technological development in general.', tag: 'Westernisation and cultural imperialism' },
    { q: 'Cultural imperialism (or cultural imposition) refers to:', options: ['The peaceful, mutual exchange of cultural traits between equal partners', 'The dominance or imposition of one culture\u2019s values and practices over another, often linked to unequal power relationships', 'A term with no connection to global power dynamics', 'A process that only occurs through military conquest'], correct: 1, explain: 'Cultural imperialism (or cultural imposition) refers to the dominance or imposition of one culture\u2019s values and practices over another, often linked to unequal power relationships, such as the global economic or media influence of powerful countries or corporations over less powerful ones.', misconception: 'Cultural imperialism is sometimes assumed to only occur through direct historical colonisation, when it can also occur through more subtle modern mechanisms, such as global media and consumer brand influence, still rooted in unequal power relationships.', tag: 'Westernisation and cultural imperialism' },
    { q: 'Detraditionalisation refers to:', options: ['The strengthening of traditional cultural practices over time', 'A decline in the influence of traditional customs, beliefs, and practices, often associated with modernisation and globalisation', 'A term unrelated to cultural change', 'A process that only affects rural communities'], correct: 1, explain: 'Detraditionalisation describes a decline in the influence and practice of traditional customs, beliefs, and practices within a society, often associated with the pressures and influences of modernisation and globalisation.', misconception: 'Detraditionalisation is sometimes assumed to mean traditions completely disappear, when it more accurately describes a general decline in their influence and prevalence, which can occur to varying degrees.', tag: 'The global spectrum of culture' },
    { q: 'The "global spectrum of culture" widening or narrowing at different scales illustrates that:', options: ['Cultural diversity changes uniformly and identically everywhere in the world', 'The balance between cultural diversity (differentialism) and cultural convergence (homogenisation) can vary significantly between different places and scales, from local communities to entire nations', 'Culture never changes at any scale', 'Only global-scale cultural change is worth studying, with no relevance at the local scale'], correct: 1, explain: 'The idea of the spectrum widening or narrowing at different scales illustrates that the balance between cultural diversity (differentialism) and cultural convergence (homogenisation) can vary significantly between different places and scales \u2014 a local community (such as an international school) might show a very different pattern of cultural diversity compared to an entire nation or the world as a whole.', misconception: 'Cultural change is sometimes assumed to happen uniformly and identically everywhere, when the reality is that patterns of diversity, homogenisation and hybridisation can look quite different depending on the specific scale and place being examined.', tag: 'The global spectrum of culture' }
  ]
};

window.SBL_LESSONS['HD-t2-l2-the-effects-of'] = {
  id: 'HD-t2-l2-the-effects-of',
  topicNumber: 2,
  topicTitle: 'Changing identities and cultures',
  title: 'The effects of global interactions on cultural diversity',
  href: '/geography/paper-2/hl-2/t2-changing/l2-the-effects-of',
  syllabusFocus: 'The effects of global interactions on cultural diversity in different places: the diffusion of cultural traits and cultural imperialism; glocalization of branded commodities and cultural hybridity; and cultural landscape changes in the built environment, using the example of Dubai.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'Diffusion of cultural traits', request: 'Explain how cultural traits diffuse and spread between places' },
    { label: 'Glocalisation', request: 'Explain what glocalisation is, using branded commodities as an example' },
    { label: 'Glocalisation as cultural imperialism', request: 'Explain how glocalisation can be seen as an example of cultural imperialism' },
    { label: 'Cultural landscape change', request: 'Explain how global interactions can change the cultural landscape of the built environment' },
    { label: 'The Dubai case study', request: 'Teach me the Dubai case study on cultural landscape change and homogenisation' },
    { label: 'Comparing cultural traits', request: 'Compare specific cultural traits with those associated with a global culture' },
    { label: 'Evaluating cultural change', request: 'Help me evaluate the positive and negative effects of global interactions on cultural diversity' }
  ],
  checklist: [
    'I can describe how glocalisation can be seen as an example of cultural imperialism.',
    'I can identify specific cultural traits and compare these with those traits associated with a global culture.',
    'I can describe how Dubai is an example where the homogenisation of landscape has occurred, especially in the built environment.'
  ],
  readinessQuestions: [
    'How do cultural traits diffuse between places?',
    'What is glocalisation, and can you give an example?',
    'How can glocalisation be seen as a form of cultural imperialism, even though it appears to adapt to local cultures?',
    'How has Dubai\u2019s built environment reflected the homogenisation of landscapes?',
    'What is one positive and one negative effect of global interactions on cultural diversity?'
  ],
  quiz: [
    { q: 'The diffusion of cultural traits refers to:', options: ['Cultural traits remaining permanently confined to their place of origin', 'The spread of cultural traits, such as food, fashion or media, from one place to another over time', 'A term unrelated to global interactions', 'Only the spread of language between countries'], correct: 1, explain: 'The diffusion of cultural traits describes the spread of cultural elements, such as food, fashion, music or media, from their place of origin to other places over time, often accelerated by global interactions like trade, migration and communication technology.', misconception: 'Cultural traits are sometimes assumed to stay fixed in their place of origin, when the process of diffusion means many cultural traits become widely adopted far beyond where they first developed.', tag: 'Diffusion of cultural traits' },
    { q: 'Glocalisation refers to:', options: ['A global brand being sold in an identical form in every country with no local adaptation', 'The process by which global brands or products are adapted to fit local cultural tastes and preferences in different markets', 'The complete rejection of any global brands by local markets', 'A term unrelated to global business strategy'], correct: 1, explain: 'Glocalisation describes the process by which global brands or products are adapted to fit local cultural tastes and preferences in different markets, combining "global" and "local" \u2014 for example, a global fast food chain adjusting its menu to suit local cuisine in different countries.', misconception: 'Glocalisation is sometimes assumed to mean a product is fully "localised" with no remaining global influence, when it specifically describes a blend \u2014 a globally standardised brand making local adaptations, rather than becoming a genuinely local product.', tag: 'Glocalisation' },
    { q: 'Glocalisation can be seen as an example of cultural imperialism because:', options: ['It has no connection to global brand influence at all', 'Even while adapting to local tastes, it still represents the continued global expansion and dominance of a foreign (often Western) brand into local markets and cultural spaces', 'It always eliminates the influence of the global brand entirely', 'Local businesses always dominate over global brands as a result'], correct: 1, explain: 'Glocalisation can be seen as a form of cultural imperialism because, even while making surface-level adaptations to local tastes, the underlying strategy still represents the continued global expansion and commercial dominance of a foreign (often Western) brand into local markets and cultural spaces, extending its influence rather than genuinely ceding ground to local alternatives.', misconception: 'Glocalisation is sometimes seen as a purely respectful, culturally sensitive strategy with no power dynamic involved, when a critical geographical perspective recognises it can still represent a form of cultural imperialism, using local adaptation as a means of continued global market expansion.', tag: 'Glocalisation as cultural imperialism' },
    { q: 'Cultural hybridity, in the context of glocalisation, describes:', options: ['A complete rejection of any cultural blending', 'The blending of global and local cultural elements to create a new, hybrid product or cultural form', 'A term unrelated to global brands', 'Only the blending of two entirely different global brands'], correct: 1, explain: 'Cultural hybridity in this context describes the blending of global and local cultural elements to create a new, hybrid product or cultural form \u2014 such as a global fast food chain\u2019s menu incorporating genuinely local ingredients or dishes alongside its standard global offerings.', misconception: 'Hybridity is sometimes confused with simple product variation; genuine cultural hybridity involves a real blending of distinct cultural elements, not just minor cosmetic differences between markets.', tag: 'Glocalisation' },
    { q: 'Cultural landscape change in the built environment refers to:', options: ['Changes to a country\u2019s natural, unbuilt landscape only', 'Changes to human-made structures, architecture and urban design that reflect shifting cultural influences, often linked to global interactions', 'A term unrelated to globalisation', 'Only changes that occur underground'], correct: 1, explain: 'Cultural landscape change in the built environment refers to changes in human-made structures, architecture and urban design that reflect shifting cultural influences, often driven or accelerated by global interactions such as international investment, tourism, and the influence of global architectural styles and brands.', misconception: 'Cultural landscape change is sometimes assumed to only relate to natural environments, when it specifically concerns human-made, built environments and how their design reflects (and sometimes homogenises) cultural influence.', tag: 'Cultural landscape change' },
    { q: 'Dubai is used as a case study of homogenisation in the built environment mainly because it:', options: ['Has remained architecturally unchanged since the pre-oil era', 'Has developed a skyline and built environment featuring many globally recognisable architectural styles and international luxury brands, similar to patterns seen in other major global cities', 'Has completely rejected any international architectural influence', 'Has no connection to global investment or tourism'], correct: 1, explain: 'Dubai is used as a case study because its rapid development has produced a skyline and built environment featuring many globally recognisable architectural styles, international luxury brands, and high-rise designs similar to patterns seen in other major global cities, illustrating how global investment and tourism can drive homogenisation of the urban landscape.', misconception: 'Dubai\u2019s built environment is sometimes assumed to be uniquely local in character, when a key geographical point of the case study is precisely how its rapid, internationally-driven development has produced landscape features closely mirroring other global cities, exemplifying homogenisation.', tag: 'The Dubai case study' },
    { q: 'A driver behind Dubai\u2019s cultural landscape change has been:', options: ['A complete lack of any international investment', 'Significant international investment, tourism development, and a deliberate strategy to position the city as a global business and luxury tourism hub', 'A policy of discouraging all foreign visitors and investment', 'Isolation from the global economy'], correct: 1, explain: 'A key driver behind Dubai\u2019s cultural landscape change has been significant international investment, tourism development, and a deliberate government strategy to position the city as a global business and luxury tourism hub, attracting international architecture, brands and investment that have reshaped its built environment.', misconception: 'Rapid urban transformation like Dubai\u2019s is sometimes seen as accidental or organic, when it specifically reflects a deliberate development strategy aimed at attracting global investment and establishing international prominence.', tag: 'The Dubai case study' },
    { q: 'A specific cultural trait (such as a traditional local dish or clothing style) differs from traits associated with a "global culture" because:', options: ['They are always identical with no meaningful difference', 'Specific cultural traits are typically rooted in and closely associated with a particular local place and history, while global culture traits (like certain international brands or media) are widely recognised and consumed across many different places', 'Specific cultural traits have no connection to place at all', 'Global culture traits are always older and more traditional than specific local traits'], correct: 1, explain: 'Specific cultural traits are typically rooted in and closely associated with a particular local place and history (such as a traditional dish or clothing style unique to one region), while traits associated with a "global culture" (like certain international brands, media franchises or consumer products) are widely recognised and consumed across many different, often unrelated, places.', misconception: 'It is sometimes assumed there is no meaningful distinction between "local" and "global" cultural traits, when comparing specific, place-rooted traits against widely recognised global culture traits is a useful way to understand the tension between cultural diversity and homogenisation.', tag: 'Comparing cultural traits' },
    { q: 'A potential positive effect of global interactions on cultural diversity is that they can:', options: ['Only ever have negative effects on local culture', 'Introduce new cultural influences, ideas and hybrid cultural forms that can enrich and diversify a local culture, alongside potential risks of homogenisation', 'Guarantee the complete disappearance of all local cultures', 'Have no measurable effect on cultural diversity at all'], correct: 1, explain: 'A recognised positive effect of global interactions is that they can introduce new cultural influences, ideas, and hybrid cultural forms that can enrich and diversify a local culture (such as new cuisines, music genres or artistic styles), even while there remain genuine risks of homogenisation and cultural imperialism to weigh against these benefits.', misconception: 'Global interactions\u2019 effect on culture is sometimes presented as entirely negative (homogenisation/imperialism) or entirely positive (enrichment/hybridity); a balanced evaluation recognises that both genuine benefits and risks exist simultaneously.', tag: 'Evaluating cultural change' },
    { q: 'When evaluating the overall effects of global interactions on cultural diversity, a strong geographical response would:', options: ['Focus only on a single example with no wider consideration of scale or place', 'Consider how effects can vary significantly between different places and scales, weighing genuine benefits (such as hybridity and new cultural exchange) against genuine risks (such as homogenisation and cultural imperialism)', 'Assume the effects are always identical everywhere in the world', 'Ignore any real-world case study evidence, such as Dubai or glocalisation examples'], correct: 1, explain: 'A strong evaluative response considers how the effects of global interactions on cultural diversity can vary significantly between different places and scales, weighing genuine benefits (such as cultural hybridity and enriching cultural exchange) against genuine risks (such as homogenisation and cultural imperialism), and grounding this in real-world evidence such as glocalisation strategies or the Dubai case study.', misconception: 'Evaluation is sometimes reduced to picking one single, universal conclusion, when geographers are expected to show how outcomes can genuinely vary by place and scale, supported by specific case study evidence.', tag: 'Evaluating cultural change' }
  ]
};

window.SBL_LESSONS['HD-t2-l3-how-diasporas'] = {
  id: 'HD-t2-l3-how-diasporas',
  topicNumber: 2,
  topicTitle: 'Changing identities and cultures',
  title: 'How diasporas influence cultural diversity and identity \u2014 Chinatown in London',
  href: '/geography/paper-2/hl-2/t2-changing/l3-how-diasporas',
  syllabusFocus: 'How diasporas influence cultural diversity and identity at both global and local scales, including a case study of a global diaspora population and its cultures, such as the Chinese diaspora.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is a diaspora?', request: 'Define diaspora and explain the role of diasporas in maintaining a culture abroad' },
    { label: 'The Chinese diaspora worldwide', request: 'Describe the presence of Chinese diasporas worldwide' },
    { label: 'Chinese diaspora case study', request: 'Summarise the importance of a specific Chinese diaspora community, such as in San Francisco or London' },
    { label: 'Diasporas at global and local scales', request: 'Explain how diasporas influence cultural diversity and identity at both global and local scales' },
    { label: 'Diaspora communities and identity', request: 'Explain how diaspora communities help maintain a sense of cultural identity abroad' },
    { label: 'Applying the IB essay mark scheme', request: 'Help me apply the IB essay mark scheme to a question about diasporas, using the Chinese diaspora as an example' },
    { label: 'Help me structure an essay', request: 'Help me plan an essay answer on the topic of diasporas' }
  ],
  checklist: [
    'I can define and explain the role of diasporas in maintaining a culture abroad.',
    'I can describe the presence of Chinese diasporas worldwide and summarise the importance of a specific Chinese diaspora community.',
    'I can apply the IB essay mark scheme to an answer on the topic of diasporas.'
  ],
  readinessQuestions: [
    'What is a diaspora, in your own words?',
    'How do diaspora communities help maintain a culture abroad?',
    'Where are some significant Chinese diaspora communities found around the world?',
    'What makes a specific Chinese diaspora community, such as in San Francisco, significant?',
    'How do diasporas influence cultural diversity at both a global and local scale?'
  ],
  quiz: [
    { q: 'A diaspora is best defined as:', options: ['A group of people who have never left their country of origin', 'A population of people who have dispersed from their original homeland to live in other parts of the world, while often maintaining connections to their culture of origin', 'A term unrelated to migration', 'A single country\u2019s entire population'], correct: 1, explain: 'A diaspora refers to a population of people who have dispersed from their original homeland to live in other parts of the world, often while maintaining cultural, social or emotional connections to their place and culture of origin.', misconception: 'A diaspora is sometimes confused with migration in general; a diaspora specifically refers to the resulting dispersed population and its ongoing cultural connections, not simply the act of moving.', tag: 'What is a diaspora?' },
    { q: 'Diaspora communities help maintain a culture abroad partly by:', options: ['Completely severing all connections to their culture of origin', 'Establishing cultural institutions, businesses, places of worship, and community networks that preserve and pass on cultural traditions in their new location', 'Refusing to interact with the host country\u2019s population at all', 'Having no measurable impact on cultural diversity in their new location'], correct: 1, explain: 'Diaspora communities often help maintain a culture abroad by establishing cultural institutions, businesses, places of worship, and community networks that help preserve and pass on cultural traditions, language and practices in their new location.', misconception: 'Diaspora communities are sometimes assumed to simply assimilate completely, losing connection to their culture of origin, when many diaspora communities actively work to preserve and pass on cultural practices across generations.', tag: 'What is a diaspora?' },
    { q: 'Chinese diaspora communities are found:', options: ['Only within mainland China itself', 'In significant numbers across many countries and cities worldwide, including North America, Europe, and Southeast Asia', 'Nowhere outside of a single specific country', 'Only in countries with no other diaspora populations'], correct: 1, explain: 'Chinese diaspora communities are found in significant numbers across many countries and cities worldwide, including major concentrations in North America, Europe, and throughout Southeast Asia, reflecting centuries of migration.', misconception: 'The scale and global reach of the Chinese diaspora is sometimes underestimated; it represents one of the largest and most geographically widespread diaspora populations in the world.', tag: 'The Chinese diaspora worldwide' },
    { q: 'A "Chinatown" district in a city such as San Francisco or London is significant because it:', options: ['Has no connection to the local Chinese diaspora community', 'Represents a concentrated area where Chinese diaspora culture, businesses, and community institutions are particularly visible and established', 'Only exists as a historical curiosity with no present-day relevance', 'Is identical in every city around the world with no local variation'], correct: 1, explain: 'A "Chinatown" district represents a concentrated area within a city where Chinese diaspora culture, businesses (such as restaurants and shops), and community institutions are particularly visible and established, often serving as both a cultural hub for the diaspora community and a point of interaction with the wider host city population.', misconception: 'Chinatown districts are sometimes viewed only as tourist attractions, when they represent genuine, functioning centres of diaspora community life, culture and identity, even while also serving a role in the wider city\u2019s cultural landscape.', tag: 'Chinese diaspora case study' },
    { q: 'A Chinese diaspora community in a city like San Francisco illustrates the influence of diasporas at which scale(s)?', options: ['Only at the global scale, with no local relevance', 'At both a local scale (visible influence on the specific neighbourhood/city) and a global scale (part of a much wider international Chinese diaspora network)', 'Only at the local scale, with no connection to a wider global diaspora', 'Diasporas have no meaningful connection to either scale'], correct: 1, explain: 'A Chinese diaspora community in a specific city like San Francisco illustrates diaspora influence at both scales simultaneously: a clear local-scale influence on that specific neighbourhood and city, and a connection to a much wider global-scale Chinese diaspora network spanning many countries.', misconception: 'Diaspora influence is sometimes considered only at a single scale, when a genuinely strong geographical answer recognises how the same diaspora community operates and has influence at both local and global scales simultaneously.', tag: 'Diasporas at global and local scales' },
    { q: 'Diaspora communities can influence cultural diversity in their host country by:', options: ['Having no measurable influence on the host country\u2019s cultural landscape', 'Introducing new cultural traits (such as cuisine, festivals, and traditions) that can become part of the host country\u2019s broader cultural diversity, sometimes leading to cultural hybridity', 'Completely replacing the host country\u2019s existing culture', 'Only influencing cultural diversity within their own community, with no wider effect'], correct: 1, explain: 'Diaspora communities can influence cultural diversity in their host country by introducing new cultural traits, such as cuisine, festivals and traditions, which can become recognised and adopted as part of the host country\u2019s broader cultural diversity, sometimes leading to genuine cultural hybridity over time.', misconception: 'The cultural influence of diaspora communities on their host country is sometimes overlooked, when specific diaspora contributions (such as widely enjoyed cuisines originating from diaspora communities) demonstrate a genuine, lasting effect on host country cultural diversity.', tag: 'Diaspora communities and identity' },
    { q: 'When writing an IB-style essay on the topic of diasporas, a strong response would typically need to:', options: ['Only describe facts about a diaspora with no analysis or evaluation', 'Use specific case study evidence (such as a named diaspora community), apply relevant terminology, and address the specific command term of the question (such as "evaluate" or "discuss")', 'Avoid using any real-world examples entirely', 'Simply repeat the question without providing any evidence'], correct: 1, explain: 'A strong IB-style essay response on diasporas would typically need to use specific case study evidence (such as a named diaspora community and location), apply relevant geographical terminology accurately, and directly address the specific command term of the question (such as "evaluate," "discuss," or "examine").', misconception: 'Essay responses are sometimes written as a general description with no specific evidence, when the IB mark scheme specifically rewards responses that combine accurate terminology, named case study evidence, and a direct response to the command term used in the question.', tag: 'Applying the IB essay mark scheme' },
    { q: 'The IB essay mark scheme for a question on diasporas would generally reward a response that:', options: ['Contains only vague, general statements with no specific evidence', 'Demonstrates accurate knowledge of the topic, applies it specifically to named case study evidence, and shows a clear line of reasoning or argument in response to the question', 'Repeats the same point multiple times without development', 'Ignores the specific wording and command term of the question entirely'], correct: 1, explain: 'The IB essay mark scheme generally rewards a response that demonstrates accurate knowledge of the topic, applies that knowledge specifically to named case study evidence (rather than staying vague or general), and develops a clear line of reasoning or argument that directly addresses the question asked.', misconception: 'It is sometimes assumed simply including more content automatically earns more marks, when the mark scheme specifically rewards precision, accurate application of evidence, and clear reasoning, rather than volume alone.', tag: 'Applying the IB essay mark scheme' },
    { q: 'A useful essay-writing strategy when discussing a diaspora case study, such as the Chinese diaspora in San Francisco, is to:', options: ['Only mention the location name with no further specific detail', 'Include specific, accurate details about the community (such as its scale, history, cultural institutions, and influence) to demonstrate genuine case study knowledge rather than a generic answer', 'Avoid mentioning any specific place names at all', 'Write about a completely different, unrelated case study instead'], correct: 1, explain: 'A useful essay-writing strategy is to include specific, accurate details about the named case study community \u2014 such as its scale, history, key cultural institutions, and specific influence on the local area \u2014 to demonstrate genuine case study knowledge rather than a generic, unsupported answer.', misconception: 'Simply naming a place is sometimes assumed to be sufficient case study evidence, when genuinely strong essay responses go further by including specific, accurate supporting detail about that named example.', tag: 'Chinese diaspora case study' },
    { q: 'Overall, studying diasporas like the Chinese diaspora helps geographers understand:', options: ['A topic with no real-world relevance to cultural diversity or identity', 'How migration and cultural connection across borders can shape identity and cultural diversity at both local and global scales, even long after the initial migration has occurred', 'That diaspora communities have no lasting cultural influence anywhere', 'Only historical migration patterns with no relevance to the present day'], correct: 1, explain: 'Studying diasporas like the Chinese diaspora helps geographers understand how migration and ongoing cultural connection across borders can shape identity and cultural diversity at both local and global scales, often continuing to have significant cultural influence long after the initial migration took place, sometimes across multiple generations.', misconception: 'Diaspora communities are sometimes considered a purely historical topic, when their ongoing cultural influence and evolving identity remain a genuinely current and significant area of study in human geography.', tag: 'Diasporas at global and local scales' }
  ]
};

window.SBL_LESSONS['HD-t3-l1-local-and-civil'] = {
  id: 'HD-t3-l1-local-and-civil',
  topicNumber: 3,
  topicTitle: 'Local responses to global interactions',
  title: 'Local and civil society resistance to global interactions',
  href: '/geography/paper-2/hl-2/t3-local-responses/l1-local-and-civil',
  syllabusFocus: 'Local and civil society resistance to global interactions: rejection of globalized production, including campaigns against TNCs and in favour of local sourcing of food and goods by citizens (such as Greenpeace campaigns against Asia Pulp and Paper and the ramin paper trail, and Thailand\u2019s \u2018Eat Local\u2019 movement); and the rise of anti-immigration movements (such as the Minutemen border patrol in the US).',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is anti-globalisation resistance?', request: 'Explain what is meant by local and civil society resistance to global interactions' },
    { label: 'Asia Pulp and Paper campaign', request: 'Explain what Asia Pulp and Paper (APP) is and summarise the Greenpeace campaign against the company' },
    { label: 'The ramin paper trail campaign', request: 'Explain the ramin paper trail environmental issue and summarise the Greenpeace campaign' },
    { label: 'The anti-Starbucks movement', request: 'Explain the opposition to Starbucks in terms of globalisation and global interactions' },
    { label: '\u2018Eat Local\u2019 in Thailand', request: 'Summarise the reasons for the \u2018Eat Local\u2019 movement at a national level in Thailand' },
    { label: 'Anti-immigration movements', request: 'Explain the rise of anti-immigration movements, such as the Minutemen border patrol in the US' },
    { label: 'Evaluating civil resistance movements', request: 'Help me evaluate the usefulness of civil movements as a form of resistance to globalisation' }
  ],
  checklist: [
    'I can identify how the ways in which the anti-globalisation movement can be manifested.',
    'I can describe the opposition to Starbucks in terms of globalisation and global interactions.',
    'I can summarise the reasons for the \u2018Eat Local\u2019 movement at a national level (Thailand).',
    'I can evaluate the usefulness of civil movements, with particular reference to the Minutemen border patrol in the US.'
  ],
  readinessQuestions: [
    'What is Asia Pulp and Paper, and what environmental concerns have been raised about the company?',
    'What was the ramin paper trail campaign, and what did Greenpeace achieve?',
    'Why has there been opposition to Starbucks in some places?',
    'Why do some people in Thailand favour eating and buying more locally produced food?',
    'What is the Minutemen border patrol, and how does it relate to anti-immigration movements in the US?'
  ],
  quiz: [
    { q: 'Local and civil society resistance to global interactions can be understood as:', options: ['A term with no real-world manifestation', 'The various ways in which individuals, communities and organisations push back against or resist aspects of globalisation, such as global production, TNC influence, or immigration', 'A process that only occurs in high-income countries', 'A movement that has no connection to environmental or economic issues'], correct: 1, explain: 'Local and civil society resistance to global interactions refers to the various ways individuals, communities and organisations push back against or resist aspects of globalisation, such as campaigning against TNCs, favouring local production, or opposing immigration, often motivated by environmental, economic, cultural or social concerns.', misconception: 'Resistance to globalisation is sometimes assumed to be a single, uniform movement, when it actually takes many different forms depending on the specific concern (environmental, economic, cultural) and the actors involved.', tag: 'What is anti-globalisation resistance?' },
    { q: 'Asia Pulp and Paper (APP) is a company that has faced environmental campaigns primarily because of concerns relating to:', options: ['Its complete absence of any manufacturing operations', 'Deforestation and unsustainable logging practices linked to its paper and pulp production, particularly in Indonesia', 'Its operations being based exclusively in high-income countries', 'A lack of any connection to global supply chains'], correct: 1, explain: 'Asia Pulp and Paper (APP), a major paper and pulp producer operating primarily in Indonesia, has faced significant environmental campaigns due to concerns about deforestation and unsustainable logging practices linked to its production, threatening rainforest habitats and biodiversity.', misconception: 'Large TNCs in the paper/pulp industry are sometimes assumed to have no significant environmental footprint, when companies like APP have specifically faced major campaigns due to documented deforestation concerns.', tag: 'Asia Pulp and Paper campaign' },
    { q: 'Greenpeace\u2019s campaign against Asia Pulp and Paper primarily aimed to:', options: ['Support the company\u2019s continued unsustainable logging practices', 'Raise public awareness and pressure the company (and its customers) to change its sourcing and logging practices to reduce deforestation', 'Have no connection to environmental concerns at all', 'Encourage governments to increase deforestation rates'], correct: 1, explain: 'Greenpeace\u2019s campaign against Asia Pulp and Paper primarily aimed to raise public awareness of the company\u2019s deforestation practices and pressure both the company and its business customers (such as major global brands) to change sourcing practices and reduce associated deforestation.', misconception: 'Environmental campaigns against TNCs are sometimes assumed to target only the company directly, when campaigns like this one also strategically target the company\u2019s customers and business partners to create wider commercial pressure for change.', tag: 'Asia Pulp and Paper campaign' },
    { q: 'The "ramin paper trail" campaign specifically focused on:', options: ['A completely unrelated environmental issue with no connection to logging', 'Tracing the illegal logging and trade of ramin, a protected tropical hardwood, through supply chains to end consumer products', 'Promoting increased consumption of ramin wood products', 'A campaign with no involvement from Greenpeace'], correct: 1, explain: 'The "ramin paper trail" campaign specifically focused on tracing the illegal logging and trade of ramin, a protected tropical hardwood species, through international supply chains to expose how it was ending up in consumer products, despite legal protections.', misconception: 'Environmental supply chain campaigns are sometimes seen as vague or symbolic, when campaigns like the ramin paper trail specifically involved detailed tracing of a protected species through real supply chains to demonstrate illegal trade.', tag: 'The ramin paper trail campaign' },
    { q: 'A notable success or outcome associated with campaigns like the ramin paper trail has been:', options: ['No measurable impact on corporate behaviour or awareness whatsoever', 'Raising public and corporate awareness of illegal logging supply chains, contributing to pressure for greater supply chain transparency and accountability', 'An increase in illegal logging as a direct result of the campaign', 'Complete elimination of all logging industries worldwide'], correct: 1, explain: 'A notable outcome of campaigns like the ramin paper trail has been raising public and corporate awareness of illegal logging supply chains, contributing to broader pressure on companies and governments for greater supply chain transparency and accountability regarding the sourcing of forest products.', misconception: 'Environmental campaigns are sometimes assumed to have no measurable real-world effect, when raising awareness and shifting corporate/consumer pressure on supply chain practices is itself a recognised and meaningful form of campaign success.', tag: 'The ramin paper trail campaign' },
    { q: 'Opposition to Starbucks, in the context of globalisation and global interactions, has often centred on concerns that the company:', options: ['Has no presence outside its home country', 'Represents the global expansion and dominance of a large TNC, potentially displacing local, independently owned coffee shops and businesses', 'Only sources its coffee from a single country with no global supply chain', 'Has faced no criticism or opposition anywhere in the world'], correct: 1, explain: 'Opposition to Starbucks has often centred on concerns that the company represents the global expansion and commercial dominance of a large TNC, with critics arguing this can displace local, independently owned coffee shops and businesses, and contribute to the broader homogenisation of local high streets and consumer culture.', misconception: 'Opposition to large global brands like Starbucks is sometimes seen as purely about product quality, when the underlying geographical concern in this context is specifically about the broader effects of TNC expansion on local businesses and cultural/economic diversity.', tag: 'The anti-Starbucks movement' },
    { q: 'The \u2018Eat Local\u2019 movement in Thailand (particularly in Bangkok) has been driven by a combination of factors including:', options: ['A complete absence of any social, economic, or environmental motivation', 'Social factors (supporting local communities and traditions), economic factors (supporting local farmers and producers), and environmental factors (reducing the environmental footprint of long-distance food transport)', 'Only economic factors, with no social or environmental relevance at all', 'A government ban on all imported food products'], correct: 1, explain: 'The \u2018Eat Local\u2019 movement in Thailand has been driven by a combination of social factors (supporting local communities and food traditions), economic factors (supporting local farmers and producers rather than global supply chains), and environmental factors (reducing the environmental footprint associated with long-distance food transport).', misconception: '\u2018Eat Local\u2019 movements are sometimes assumed to be driven by a single motivation (often assumed to be purely environmental), when in reality they typically combine social, economic and environmental reasoning together.', tag: '\u2018Eat Local\u2019 in Thailand' },
    { q: 'The \u2018Eat Local\u2019 movement represents a form of opposition to globalisation because it:', options: ['Actively encourages increased reliance on globally sourced, imported food products', 'Deliberately favours locally produced food and goods over globally sourced alternatives, reflecting a preference for local economic and cultural connection over global supply chains', 'Has no connection to consumer choices or food sourcing at all', 'Is identical in every way to a typical global fast food chain\u2019s business model'], correct: 1, explain: 'The \u2018Eat Local\u2019 movement represents a form of opposition to globalisation because it deliberately favours locally produced food and goods over globally sourced alternatives, reflecting a conscious preference for supporting local economic and cultural connections rather than relying on globalised supply chains.', misconception: 'Consumer movements like \u2018Eat Local\u2019 are sometimes viewed as unrelated to globalisation debates, when they represent a genuinely deliberate, everyday form of resistance to globalised food systems and production.', tag: '\u2018Eat Local\u2019 in Thailand' },
    { q: 'The rise of anti-immigration movements, such as the Minutemen border patrol in the US, can be understood as:', options: ['Having no connection whatsoever to global interactions or migration', 'A form of civil society resistance to increased global migration flows, often motivated by concerns about national identity, economic competition, or border security', 'A movement that exclusively supports increased immigration', 'A government-run official border security agency'], correct: 1, explain: 'The rise of anti-immigration movements, such as the Minutemen border patrol (a volunteer civilian group that monitored the US-Mexico border), can be understood as a form of civil society resistance to increased global migration flows, often motivated by concerns about national identity, economic competition for jobs, or border security.', misconception: 'The Minutemen are sometimes assumed to be an official government agency, when they were specifically a volunteer, non-governmental civilian group, illustrating civil society (rather than state) resistance to immigration.', tag: 'Anti-immigration movements' },
    { q: 'When evaluating the usefulness of civil society movements as a form of resistance to globalisation, geographers would consider that they can:', options: ['Have no meaningful effect on raising awareness or influencing policy debate, regardless of the specific movement', 'Effectively raise public awareness and sometimes influence corporate or government policy, though their overall effectiveness and legitimacy can vary and generate genuine debate, depending on the specific movement and its methods', 'Always achieve complete and immediate success in every case with no possible criticism', 'Only ever be evaluated positively, regardless of a movement\u2019s specific goals or methods'], correct: 1, explain: 'A balanced evaluation of civil society movements (from environmental campaigns like the ramin paper trail, to anti-Starbucks or Eat Local movements, to anti-immigration groups like the Minutemen) recognises that such movements can effectively raise public awareness and sometimes influence corporate or government policy, though their overall effectiveness, methods, and legitimacy can vary considerably and generate genuine debate depending on the specific movement in question.', misconception: 'Civil society movements are sometimes evaluated as uniformly positive or uniformly ineffective, when a genuinely strong evaluation recognises that different movements vary significantly in their methods, legitimacy, and effectiveness, and can generate real debate.', tag: 'Evaluating civil resistance movements' }
  ]
};

window.SBL_LESSONS['HD-t3-l2-geopolitical'] = {
  id: 'HD-t3-l2-geopolitical',
  topicNumber: 3,
  topicTitle: 'Local responses to global interactions',
  title: 'Geopolitical constraints on global interactions',
  href: '/geography/paper-2/hl-2/t3-local-responses/l2-geopolitical',
  syllabusFocus: 'Geopolitical constraints on global interactions: government and militia controls on personal freedoms to participate in global interactions, and national trade restrictions, including protectionism and resource nationalism.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'Government controls on freedoms', request: 'Explain how governments can restrict personal freedoms to participate in global interactions' },
    { label: 'US Executive Order 13769', request: 'Summarise how a government policy such as Executive Order 13769 has reduced global interactions' },
    { label: 'Comparing internet restrictions', request: 'Compare how internet restrictions vary between different countries worldwide' },
    { label: 'What is protectionism?', request: 'Explain what protectionism is and how it can be implemented' },
    { label: 'What is resource nationalism?', request: 'Explain what resource nationalism is' },
    { label: 'Protectionism at different levels', request: 'Explain how protectionism can be implemented at different levels and why' },
    { label: 'Evaluating geopolitical constraints', request: 'Help me evaluate the effects of geopolitical constraints on global interactions' }
  ],
  checklist: [
    'I can summarise how a government policy has reduced global interactions.',
    'I can compare the levels of internet restrictions between different countries worldwide.',
    'I can explain how protectionism can be implemented at different levels and why.'
  ],
  readinessQuestions: [
    'How can governments restrict personal freedoms to participate in global interactions?',
    'What is one example of a government policy that has reduced global interactions?',
    'Why do internet restrictions vary between different countries?',
    'What is protectionism, and what forms can it take?',
    'What is resource nationalism?'
  ],
  quiz: [
    { q: 'Geopolitical constraints on global interactions refer to:', options: ['Only physical/natural barriers, such as oceans or mountains', 'Government, political or militia-imposed restrictions that limit the ability of people, goods, or information to move and interact globally', 'A term unrelated to government policy', 'Constraints that only ever increase, never decrease, global interaction'], correct: 1, explain: 'Geopolitical constraints refer to government, political or militia-imposed restrictions \u2014 such as travel bans, internet censorship, or trade barriers \u2014 that limit the ability of people, goods, capital, or information to move and interact globally.', misconception: 'Geopolitical constraints are sometimes confused with purely physical barriers to interaction (like oceans); geopolitical constraints specifically arise from political decisions and policy, not physical geography.', tag: 'Government controls on freedoms' },
    { q: 'Government travel or immigration bans, such as restrictions targeting specific countries, represent a geopolitical constraint because they:', options: ['Have no effect on people\u2019s ability to travel or migrate internationally', 'Directly restrict the movement of people between countries, limiting global interaction through migration, travel and family/business connections', 'Only ever apply to goods, never to people', 'Automatically increase global interaction'], correct: 1, explain: 'Government travel or immigration bans directly restrict the movement of people between countries, limiting global interaction through reduced migration, travel, and disrupted family, business or educational connections between affected countries and populations.', misconception: 'Immigration policy is sometimes considered purely a domestic matter, when travel/immigration restrictions have a direct and measurable effect on the level of global interaction between the restricting country and the affected populations.', tag: 'US Executive Order 13769' },
    { q: 'A specific government policy example (such as a travel ban executive order) reducing global interactions would typically involve:', options: ['Removing all restrictions on entry to a country', 'Restricting entry into a country for citizens of specific named countries, reducing travel, migration and associated global interactions between those places', 'Having no connection to international relations at all', 'Applying identically and without exception to every country in the world'], correct: 1, explain: 'A specific policy example, such as a travel ban executive order, typically involves restricting entry into a country for citizens of specific named countries, directly reducing travel, migration and associated global interactions between the restricting country and those specifically targeted nations.', misconception: 'Government restrictions are sometimes assumed to apply universally to all countries equally, when many real-world examples specifically target selected countries, creating uneven patterns of restricted global interaction.', tag: 'US Executive Order 13769' },
    { q: 'Internet restrictions vary significantly between different countries worldwide partly because:', options: ['All countries apply identical internet policies with no variation', 'Governments have different levels of control over online content, access to specific websites/platforms, and levels of surveillance, often reflecting differing political systems and priorities', 'Internet restrictions have no connection to government policy at all', 'Internet access is identical everywhere in the world regardless of any government involvement'], correct: 1, explain: 'Internet restrictions vary significantly between countries because governments differ considerably in the level of control they exert over online content, access to specific websites or platforms, and levels of digital surveillance, often reflecting differing political systems, priorities, and attitudes towards free information flow.', misconception: 'Internet access and freedom is sometimes assumed to be relatively uniform worldwide, when significant variation exists between countries in terms of government-imposed restrictions and censorship of online global interaction.', tag: 'Comparing internet restrictions' },
    { q: 'A country with significant internet restrictions compared to one with minimal restrictions would typically show:', options: ['No meaningful difference in citizens\u2019 ability to access global information and communication platforms', 'Reduced ability for citizens to access certain global websites, social media platforms, or information sources, limiting their participation in certain forms of global digital interaction', 'Identical online experiences for citizens in both countries', 'Greater global interaction in the country with more restrictions'], correct: 1, explain: 'A country with significant internet restrictions would typically show a reduced ability for citizens to access certain global websites, social media platforms, or information sources compared to a country with minimal restrictions, limiting citizens\u2019 participation in certain forms of global digital interaction and information exchange.', misconception: 'It is sometimes assumed internet restrictions have only a minor practical effect, when significant restrictions can substantially limit citizens\u2019 genuine ability to participate in global digital communication, information access and online commerce.', tag: 'Comparing internet restrictions' },
    { q: 'Protectionism, as an economic policy, refers to:', options: ['A policy of completely open, unrestricted international trade with no barriers', 'Government policies designed to restrict international trade in order to protect domestic industries, such as tariffs, quotas, or subsidies', 'A term unrelated to trade policy', 'A policy exclusively used to increase imports'], correct: 1, explain: 'Protectionism refers to government policies designed to restrict international trade in order to protect domestic industries from foreign competition, commonly implemented through tools such as tariffs (taxes on imports), quotas (limits on import quantities), or subsidies for domestic producers.', misconception: 'Protectionism is sometimes confused with free trade policy; protectionism specifically involves deliberate government intervention to restrict trade and shield domestic industries, the opposite of an open trade approach.', tag: 'What is protectionism?' },
    { q: 'Resource nationalism refers to:', options: ['A country freely allowing unrestricted foreign ownership and control of its natural resources', 'A government policy tendency to assert increased state control over a country\u2019s natural resources, often limiting foreign ownership or investment in resource extraction', 'A term unrelated to natural resources or government policy', 'A policy that only applies to renewable energy resources'], correct: 1, explain: 'Resource nationalism refers to a government policy tendency to assert increased state control over a country\u2019s natural resources (such as oil, gas or minerals), often by limiting foreign ownership or investment in resource extraction, or by increasing state involvement and revenue capture from these industries.', misconception: 'Resource nationalism is sometimes confused with simple environmental protection policy; it specifically concerns increased state/national control and ownership over resource extraction, which can be motivated by economic or political goals rather than purely environmental ones.', tag: 'What is resource nationalism?' },
    { q: 'Protectionism can be implemented at different levels, such as:', options: ['Only ever at a single, universal global level with no variation', 'National-level tariffs on specific imported goods, or more targeted, industry-specific protections aimed at particular domestic sectors considered strategically important', 'Exclusively through military intervention', 'Only through complete national economic isolation with no partial measures possible'], correct: 1, explain: 'Protectionism can be implemented at different levels and in different forms, ranging from broad national-level tariffs applied to a wide range of imported goods, to more targeted, industry-specific protections aimed at particular domestic sectors that a government considers strategically important to protect.', misconception: 'Protectionist policy is sometimes assumed to be a single, uniform approach, when governments can apply protectionism at varying scales and with varying degrees of targeting, from broad national tariffs to narrow, sector-specific measures.', tag: 'Protectionism at different levels' },
    { q: 'A government might choose to implement protectionist trade policy in order to:', options: ['Deliberately harm its own domestic industries', 'Protect domestic jobs and industries from foreign competition, support strategically important sectors, or respond to political pressure from domestic producers', 'Increase global interaction and international trade dependency as much as possible', 'Comply with a universal international requirement that applies to every country identically'], correct: 1, explain: 'A government might implement protectionist trade policy in order to protect domestic jobs and industries from foreign competition, support sectors considered strategically important (such as agriculture or defence-related industries), or respond to political pressure from domestic producers and workers.', misconception: 'Protectionist policy is sometimes assumed to have no clear rationale, when governments typically have specific economic or political motivations \u2014 job protection, strategic industry support, or domestic political pressure \u2014 behind such decisions.', tag: 'Protectionism at different levels' },
    { q: 'Overall, geopolitical constraints such as travel restrictions, internet censorship, protectionism, and resource nationalism illustrate that:', options: ['Global interactions always increase steadily with no possible reversal or limitation', 'Government and political decisions can significantly limit or reshape the extent and nature of global interactions, even as broader globalisation trends continue elsewhere', 'These four examples have no meaningful connection to one another as a category of constraint', 'Geopolitical constraints only ever affect a single country in isolation, with no wider international consequence'], correct: 1, explain: 'Taken together, geopolitical constraints such as travel restrictions, internet censorship, protectionism, and resource nationalism illustrate that government and political decisions can significantly limit or reshape the extent and nature of global interactions for a country and its citizens, even as broader globalisation trends continue in other parts of the world, showing that globalisation is not a simple, one-directional or universally applied process.', misconception: 'Globalisation is sometimes assumed to be a simple, uniformly increasing trend affecting every country equally, when geopolitical constraints demonstrate that governments retain significant power to selectively limit or reshape global interaction for their own populations.', tag: 'Government controls on freedoms' }
  ]
};

